-- 0034_reseed_run_plans.sql
-- Y2: re-seed the run plans with correct French accents (verses are the exact
-- Louis Segond 1910 text from the app's Bible source), three distinct sessions
-- per week (easy / tempo / long) each with its own name and instructions.
-- Idempotent upserts on slug and on (plan_id, week, day_in_week). Requires the
-- instructions columns added in 0033.

insert into public.run_plans (slug, title, title_fr, description, description_fr, weeks, goal_distance_m, weeks_meta, sort_order)
values ('c5k-8', '5k in 8 weeks', '5 km en 8 semaines', 'From walk-run intervals to a continuous 5k, three sessions a week: easy, tempo and long.', 'De la marche-course au 5 km en continu, trois séances par semaine: facile, rythme et sortie longue.', 8, 5000, '[{"week":1,"verse_ref":"1 Corinthiens 9.24","verse_text":"Ne savez-vous pas que ceux qui courent dans le stade courent tous, mais qu''un seul remporte le prix? Courez de manière à le remporter.","verse_ref_en":"1 Corinthians 9:24","verse_text_en":"Don''t you know that those who run in a race all run, but one receives the prize? Run like that, that you may win.","prayer":"Seigneur, merci pour ce corps que tu m''as donné. Donne-moi de commencer avec humilité et de finir avec joie.","prayer_en":"Lord, thank you for this body you gave me. Help me begin in humility and finish with joy."},{"week":2,"verse_ref":"Hébreux 12.1","verse_text":"Nous donc aussi, puisque nous sommes environnés d''une si grande nuée de témoins, rejetons tout fardeau, et le péché qui nous enveloppe si facilement, et courons avec persévérance dans la carrière qui nous est ouverte,","verse_ref_en":"Hebrews 12:1","verse_text_en":"Therefore let us also, seeing we are surrounded by so great a cloud of witnesses, lay aside every weight and the sin which so easily entangles us, and let''s run with perseverance the race that is set before us,","prayer":"Père, quand mon souffle devient court, rappelle-moi que ta force se montre dans ma faiblesse.","prayer_en":"Father, when my breath runs short, remind me that your strength shows in my weakness."},{"week":3,"verse_ref":"Ésaïe 40.31","verse_text":"Mais ceux qui se confient en l''Éternel renouvellent leur force. Ils prennent le vol comme les aigles; Ils courent, et ne se lassent point, Ils marchent, et ne se fatiguent point.","verse_ref_en":"Isaiah 40:31","verse_text_en":"but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.","prayer":"Jésus, apprends-moi la persévérance: un pas après l''autre, un jour après l''autre, pour ta gloire.","prayer_en":"Jesus, teach me perseverance: one step after another, one day after another, for your glory."},{"week":4,"verse_ref":"2 Timothée 4.7","verse_text":"J''ai combattu le bon combat, j''ai achevé la course, j''ai gardé la foi.","verse_ref_en":"2 Timothy 4:7","verse_text_en":"I have fought the good fight. I have finished the course. I have kept the faith.","prayer":"Seigneur, je dépose ma hâte. Donne-moi un cœur paisible et des jambes fidèles sur la distance.","prayer_en":"Lord, I lay down my hurry. Give me a peaceful heart and faithful legs for the distance."},{"week":5,"verse_ref":"Philippiens 3.13-14","verse_text":"Frères, je ne pense pas l''avoir saisi; mais je fais une chose: oubliant ce qui est en arrière et me portant vers ce qui est en avant, je cours vers le but, pour remporter le prix de la vocation céleste de Dieu en Jésus-Christ.","verse_ref_en":"Philippians 3:13-14","verse_text_en":"Brothers, I don''t regard myself as yet having taken hold, but one thing I do. Forgetting the things which are behind, and stretching forward to the things which are before, I press on toward the goal for the prize of the high calling of God in Christ Jesus.","prayer":"Père, garde mes yeux fixés sur le but et mon cœur reconnaissant pour chaque foulée.","prayer_en":"Father, keep my eyes fixed on the goal and my heart thankful for every stride."},{"week":6,"verse_ref":"1 Corinthiens 9.24","verse_text":"Ne savez-vous pas que ceux qui courent dans le stade courent tous, mais qu''un seul remporte le prix? Courez de manière à le remporter.","verse_ref_en":"1 Corinthians 9:24","verse_text_en":"Don''t you know that those who run in a race all run, but one receives the prize? Run like that, that you may win.","prayer":"Seigneur, merci pour ce corps que tu m''as donné. Donne-moi de commencer avec humilité et de finir avec joie.","prayer_en":"Lord, thank you for this body you gave me. Help me begin in humility and finish with joy."},{"week":7,"verse_ref":"Hébreux 12.1","verse_text":"Nous donc aussi, puisque nous sommes environnés d''une si grande nuée de témoins, rejetons tout fardeau, et le péché qui nous enveloppe si facilement, et courons avec persévérance dans la carrière qui nous est ouverte,","verse_ref_en":"Hebrews 12:1","verse_text_en":"Therefore let us also, seeing we are surrounded by so great a cloud of witnesses, lay aside every weight and the sin which so easily entangles us, and let''s run with perseverance the race that is set before us,","prayer":"Père, quand mon souffle devient court, rappelle-moi que ta force se montre dans ma faiblesse.","prayer_en":"Father, when my breath runs short, remind me that your strength shows in my weakness."},{"week":8,"verse_ref":"Ésaïe 40.31","verse_text":"Mais ceux qui se confient en l''Éternel renouvellent leur force. Ils prennent le vol comme les aigles; Ils courent, et ne se lassent point, Ils marchent, et ne se fatiguent point.","verse_ref_en":"Isaiah 40:31","verse_text_en":"but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.","prayer":"Jésus, apprends-moi la persévérance: un pas après l''autre, un jour après l''autre, pour ta gloire.","prayer_en":"Jesus, teach me perseverance: one step after another, one day after another, for your glory."}]'::jsonb, 1)
on conflict (slug) do update set
  title = excluded.title, title_fr = excluded.title_fr,
  description = excluded.description, description_fr = excluded.description_fr,
  weeks = excluded.weeks, goal_distance_m = excluded.goal_distance_m,
  weeks_meta = excluded.weeks_meta, sort_order = excluded.sort_order;

insert into public.run_plan_sessions (plan_id, week, day_in_week, title, title_fr, instructions, instructions_fr, segments, sort_order)
