from public.run_plans p,
  (values
  (1, 1, 'Easy run', 'Footing facile', 'Run at a pace where you can talk. Alternate running and walking without straining.', 'Cours à une allure où tu peux parler. Alterne course et marche sans forcer.', '[{"kind":"warmup","seconds":300},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"run","seconds":60},{"kind":"walk","seconds":90},{"kind":"cooldown","seconds":300}]'::jsonb, 11),
